async function api<T>(path:string,body?:unknown,method=body?'POST':'GET'):Promise<T>{
 const response=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store'});
 if(response.status===401||response.status===428){location.assign('/welcome?return_to='+encodeURIComponent(location.pathname+location.search));throw new Error('Sign in to continue.');}
 const data=await response.json() as T&{error?:string};if(!response.ok)throw new Error(data.error||'This step could not be completed. Your saved content is safe.');return data as T;
}
function Field({label,value,onChange,placeholder,multiline=false,help,maxLength=6000,type='text'}:{label:string;value:string;onChange:(value:string)=>void;placeholder?:string;multiline?:boolean;help?:string;maxLength?:number;type?:string}){
 return <label className="pb-field"><span>{label}</span>{multiline?<textarea rows={4} value={value} maxLength={maxLength} placeholder={placeholder} onChange={event=>onChange(event.target.value)}/>:<input type={type} value={value} maxLength={maxLength} placeholder={placeholder} onChange={event=>onChange(event.target.value)}/>} {help&&<small>{help}</small>}</label>;
}
function TypeInputs({draft,onField}:{draft:BuilderDraft;onField:(name:string,value:string)=>void}){
 const fields=draft.fields;
 const input=(key:string,label:string,placeholder:string,multiline=false)=><Field key={key} label={label} value={fields[key]||''} onChange={value=>onField(key,value)} placeholder={placeholder} multiline={multiline}/>;
 if(draft.type==='book')return <section className="pb-card"><h2>The shape of your book</h2><p>A manuscript has its own reader journey. Define it before writing chapters.</p>{input('subtitle','Subtitle','Optional supporting promise')}{input('bookPremise','Book premise / central argument','The idea that connects the chapters.',true)}{input('readerLevel','Reader experience level','For example: complete beginner or experienced practitioner')}</section>;
 if(draft.type==='guide')return <section className="pb-card"><h2>A practical path for your reader</h2>{input('startingPoint','Reader’s starting point','What does your reader already know?')}{input('runningExample','Worked example / scenario','A realistic example to carry through the guide.',true)}</section>;
 if(draft.type==='playbook')return <section className="pb-card"><h2>Make the process repeatable.</h2>{input('trigger','When should someone use this process?','The situation or trigger that starts the workflow.',true)}{input('requiredInputs','Required inputs / tools','What someone needs before starting.')}{input('definitionOfDone','Definition of done','How someone knows they completed the process successfully.',true)}</section>;
 if(draft.type==='challenge')return <section className="pb-card"><h2>Turn your goal into daily action.</h2><div className="pb-inline-note"><CalendarDays size={17}/><p>This challenge is self-paced. Publishing does not schedule emails, cohort events, or unlock dates.</p></div>{input('dailyTime','Daily time commitment','For example: 15 minutes')}{input('completionCriteria','Completion / reflection method','What should participants record or demonstrate?',true)}</section>;
 return null;
}
