 const [pendingSuggestion,setPendingSuggestion]=useState<BuilderAgentSuggestion|null>(null),[pendingLeave,setPendingLeave]=useState<string|null>(null);
 const [uploadProgress,setUploadProgress]=useState<{name:string;percent:number}|null>(null),[slots,setSlots]=useState<CommerceSlot[]>([]),[slotStart,setSlotStart]=useState(''),[country,setCountry]=useState('US');
