 const wsRef=useRef<BuilderWorkspace|null>(null),draftRef=useRef(draft),baselineRef=useRef(''),busyRef=useRef(false),savePromise=useRef<Promise<BuilderWorkspace>|null>(null),requestId=useRef(crypto.randomUUID()),stopRef=useRef(false),leavingRef=useRef(false),xhrRef=useRef<XMLHttpRequest|null>(null),initialIdea=useRef(''),suggestionDecision=useRef<((applied:boolean)=>void)|null>(null),failedSave=useRef('');
 const dirty=!!workspace&&JSON.stringify(draft)!==baseline,info=builderTypeDetails[draft.type],family=builderFamily(draft),Icon=icons[family];
