 useEffect(()=>{if(!workspace)return;void api<AIState>('/api/workspace').then(setAI).catch(()=>{});void api<GenerationState>(`/api/builder/${workspace.product.id}/generation`).then(setGeneration).catch(()=>{});},[workspace?.product.id]);
 useEffect(()=>{const handler=(event:BeforeUnloadEvent)=>{if(!leavingRef.current&&(JSON.stringify(draftRef.current)!==baselineRef.current||busyRef.current)){event.preventDefault();event.returnValue='';}};window.addEventListener('beforeunload',handler);return()=>window.removeEventListener('beforeunload',handler);},[]);
