    xhr.onload=()=>{try{const data=JSON.parse(xhr.responseText);if(xhr.status<200||xhr.status>=300)throw new Error(data.error||'Upload failed. Select the original file and retry.');resolve(data);}catch(reason){reject(reason);}};
    xhr.onerror=()=>reject(new Error('The upload was interrupted. Your saved files are safe.'));xhr.onabort=()=>reject(new Error('Upload stopped.'));xhr.send(file);
