 function addSection(){if(draft.sections.length>=30)return;const parts=[...draft.sections,{id:crypto.randomUUID(),title:`${info.unit} ${draft.sections.length+1}`,body:''}];update({sections:parts});setActiveSection(parts.length-1);}
